export function scaleAndSum( items: number[], factor: number ): number {
    let total = 0;
    const scaled: number[] = [];
    for ( const item of items ) {
        if ( item > 10 ) {
            scaled.push( item * factor );
        } else {
            scaled.push( item + factor );
        }
    }
    for ( const s of scaled ) {
        total += s;
    }
    return total;
}

