export function distinct( path: string ): string[] {
    const parts = path.split( '/' ).filter( ( p ) => p.length > 0 );
    return parts.map( ( p ) => p.toUpperCase() ).reverse();
}

export function small( n: number ): number {
    return n + 1;
}
